cd /tmp/rl-shots && python3 - <<'EOF'
s=open('$RUN/work/index.html').read()
test="""<script>
document.querySelector('[data-billing=annual]').click();
document.querySelector('.menu-toggle').click();
document.querySelector('.faq-item').open=true;
document.getElementById('email').value='bad';
document.querySelector('#signup button').click();
var r=[...document.querySelectorAll('.plans .amt')].map(e=>e.textContent).join(',')+' | '+[...document.querySelectorAll('.price-note')].map(e=>e.textContent).join(',')+' | menu:'+document.getElementById('mobile-menu').className+' | msg:'+document.getElementById('form-msg').textContent;
document.title=r; document.body.insertAdjacentHTML('afterbegin','<pre id=res style=\"position:fixed;z-index:99;bottom:0;background:#fff;color:#000;margin:0;font-size:11px;white-space:pre-wrap\">'+r+'</pre>');
</script></body>"""
open('rl_test.html','w').write(s.replace('</body>',test))
EOF
"/Applications/Google Chrome.app/Contents/MacOS/Google Chrome" --headless=new --disable-gpu --window-size=800,600 --virtual-time-budget=3000 --dump-dom file:///tmp/rl-shots/rl_test.html 2>/dev/null | grep -o '<title>[^<]*'

